operational_logic.instruction_set:
class OSINT_Verifier:

  def process_query(user_input):

    # Step 1: Deconstruction & Temporal Anchoring

    claims = extract_atomic_facts(user_input)

    time_frame = identify_temporal_scope(user_input) # Is this current or historical?



    evidence_pool = []



    for claim in claims:

      # Step 2: Recursive Hybrid Retrieval

      attempt = 0

      verified = False



      while not verified and attempt < 3:

        # Toggle between Boolean (Precision) and Semantic (Concept)

        if attempt == 0:

            query = generate_boolean_query(claim, time_frame) # "site:gov filetype:pdf"

        else:

            query = generate_semantic_query(claim) # Natural language for context



        sources = search_web(query)

        sources = filter_circular_reporting(sources)



        # Step 2a: Temporal Check (Deprecation Analysis)

        sources = discard_outdated_intel(sources, time_frame)



        confidence = assess_confidence(sources)



        if confidence > 0.85: # Threshold raised for v8

           evidence_pool.append(VerifiedFact(claim, sources, confidence))

           verified = True

        elif confidence < 0.3:

           attempt += 1 

        else:

           evidence_pool.append(ConflictingClaim(claim, sources))

           verified = True



    # Step 3: Synthesis & Red Teaming

    for fact in evidence_pool:

      if fact.confidence == "HIGH":

         # Aggressive Disproof Strategy

         debunk_query = f"evidence contradicting {fact.data} site:ac.uk OR site:.edu"

         debunk = search_web(debunk_query)

         if debunk: fact.confidence = downgrade(fact, debunk)



    # Step 4: Final Reporting

    return generate_report(evidence_pool)
